"""Own smooth Cartesian motion planner, with simulated terminal compensation."""
import json
from pathlib import Path
import numpy as np
import mw_tool
from scipy.optimize import least_squares


def smoothstep(t):
 return t*t*t*(10-15*t+6*t*t)


def run(s, params, travel=70, hold=45, height=.24, full=False):
 s.reset()
 # A smooth mocap path first passes high above the wall, then drops behind it.
 start=s.data.mocap_pos[0].copy()
 midpoint=np.array([s.target_pos[0],.825,height])
 finish=np.asarray(params)
 durations=[int(travel*.53),travel-int(travel*.53)]
 for p0,p1,duration in [(start,midpoint,durations[0]),(midpoint,finish,durations[1])]:
  for i in range(1,duration+1):
   desired=p0+(p1-p0)*smoothstep(i/duration)
   action=np.r_[np.clip((desired-s.data.mocap_pos[0])/.01,-1,1),1]
   s.step(action)
 for _ in range(hold):s.step([0,0,0,1])
 return s.env.tcp_center-s.target_pos

if __name__=='__main__':
 s=mw_tool.Session()
 guess=np.array([.045,.935,.074])
 best=None;results=[]
 for travel in [45,55,65,75,90,110]:
  for hold in [15,25,35,45,60]:
   for height in [.205,.225,.245,.265]:
    def residual(params): return run(s,params,travel,hold,height)
    opt=least_squares(residual,guess,diff_step=1e-4,xtol=1e-10,ftol=1e-10,gtol=1e-10,max_nfev=20)
    error=run(s,opt.x,travel,hold,height)
    actions=np.array(s.actions)
    prev=s.env.tcp_center.copy();s.step([0,0,0,1]);vel=np.linalg.norm(s.env.tcp_center-prev)/.0125
    hold_error=0
    for _ in range(60):
     s.step([0,0,0,1]);hold_error=max(hold_error,np.linalg.norm(s.env.tcp_center-s.target_pos))
    result={'travel':travel,'hold':hold,'height':height,'finish':opt.x.tolist(),'error':float(np.linalg.norm(error)),'velocity':float(vel),'hold_error':float(hold_error),'steps':len(actions)}
    results.append(result)
    if np.linalg.norm(error)<1e-5 and vel<.001 and hold_error<.0005:
     if best is None or len(actions)<best['steps']:
      best=result;s.save_trajectory(actions,path='/app/experiments/best_smooth.npz',meta=result)
      print('BEST',json.dumps(result),flush=True)
    if len(results)%20==0:print('PROGRESS',len(results),flush=True)
 Path('/app/experiments/smooth_results.json').write_text(json.dumps(results,indent=2))
 print('DONE',json.dumps(best),flush=True)
 s.close()
