"""Refine a native action finish, requiring low motion as well as position error."""
import json,time
from pathlib import Path
import numpy as np
from scipy.optimize import least_squares
from fast_session import FastSession
s=FastSession();r=json.loads(Path('/app/experiments/refine_result.json').read_text())
base=np.array(r['parameters']);started=time.time();results=[]


def make_actions(p,duration):
 values=p.reshape(-1,3);a=np.ones((duration,4))
 for j in range(3):a[:,j]=np.interp(np.arange(duration),np.linspace(0,duration-1,len(values)),values[:,j])
 return a


def run(p,duration,full=False):
 s.reset();a=make_actions(p,duration);trace=[];contacts=0
 for row in a:
  s.step(row);trace.append(s.env.tcp_center.copy())
  if full:contacts+=sum(37 in [c.geom1,c.geom2] for c in s.data.contact)
 trace=np.asarray(trace);terminal=[trace[-1]]
 for i in range(80):
  s.step([0,0,0,1])
  if i in [0,2,4,9,19,39,79]:terminal.append(s.env.tcp_center.copy())
 terminal=np.asarray(terminal)
 near=(trace[:,1]>.68)&(trace[:,1]<.82)
 penalty=np.maximum(.165-trace[:,2],0)*near*1000
 velocity=(trace[-1]-trace[-2])*1000
 last_action=a[-1,:3]
 residual=np.r_[((terminal-s.target_pos)*1000).ravel(),velocity,penalty,last_action*.2]
 if full:return a,terminal,contacts,trace
 return residual

for duration in [100,110,120,90,80]:
 guess=base.ravel();evals=[0]
 def residual(p):
  evals[0]+=1
  if evals[0]%500==0:print('PROGRESS',duration,evals[0],flush=True)
  return run(p,duration)
 opt=least_squares(residual,guess,bounds=(-1,1),diff_step=1e-5,max_nfev=200,xtol=1e-10,ftol=1e-10,gtol=1e-8)
 a,terminal,contacts,trace=run(opt.x,duration,True)
 err=np.linalg.norm(terminal-s.target_pos,axis=1);vel=np.linalg.norm(trace[-1]-trace[-2])/.0125
 result={'duration':duration,'knots':len(base),'parameters':opt.x.reshape(-1,3).tolist(),'terminal_errors':err.tolist(),'contacts':contacts,'final_velocity':float(vel),'cost':opt.cost,'nfev':opt.nfev,'elapsed':time.time()-started}
 results.append(result);print(json.dumps(result),flush=True)
 s.save_trajectory(a,path=f'/app/experiments/stationary_{duration}.npz',meta=result)
 Path('/app/experiments/stationary_results.json').write_text(json.dumps(results,indent=2))
print('DONE',flush=True);s.close()
