"""Own smooth wall-clearance controller followed by precise Cartesian feedback."""
import json
from pathlib import Path
import numpy as np
from fast_session import FastSession


def move_mocap(s,finish,duration,grip=0.):
 start=s.data.mocap_pos[0].copy()
 for i in range(1,duration+1):
  t=i/duration;ease=t**3*(10-15*t+6*t*t)
  desired=start+(np.asarray(finish)-start)*ease
  s.step(np.r_[np.clip((desired-s.data.mocap_pos[0])/.01,-1,1),grip])


def run(s,durations=(35,70,60),height=.28,grip=0,gain=45,damping=40):
 s.reset();goal=s.target_pos
 move_mocap(s,[goal[0],.64,height],durations[0],grip)
 move_mocap(s,[goal[0],.94,height],durations[1],grip)
 # End point estimate, then native feedback absorbs residual weld displacement.
 move_mocap(s,[goal[0]+.0015,.945,.071],durations[2],grip)
 previous=s.env.tcp_center.copy();stable=0
 for _ in range(330):
  tcp=s.env.tcp_center.copy();error=goal-tcp;delta=tcp-previous;previous=tcp
  s.step(np.r_[np.clip(gain*error-damping*delta,-1,1),grip])
  err=np.linalg.norm(s.env.tcp_center-goal);vel=np.linalg.norm(s.env.tcp_center-tcp)/.0125
  stable=stable+1 if err<1e-7 and vel<1e-6 else 0
  if stable>=10:break
 if len(s.actions)>500:return None
 a=np.array(s.actions)
 if stable<10:return None
 hold_max=0
 for _ in range(80):s.step([0,0,0,grip]);hold_max=max(hold_max,np.linalg.norm(s.env.tcp_center-goal))
 return {'durations':durations,'height':height,'grip':grip,'gain':gain,'damping':damping,'steps':len(a),'error':float(err),'velocity':float(vel),'hold_error':float(hold_max)},a

if __name__=='__main__':
 s=FastSession();best=None;results=[]
 for durations in [(35,70,60),(25,60,50),(40,90,75),(45,100,90)]:
  for height in [.26,.28,.30]:
   for grip in [0,-1,.01]:
    for gain,damping in [(30,20),(45,40),(60,60),(80,80)]:
     r=run(s,durations,height,grip,gain,damping)
     if r is None:continue
     result,a=r;results.append(result)
     if result['hold_error']<2e-6 and (best is None or result['steps']<best['steps']):
      best=result;s.save_trajectory(a,path='/app/experiments/best_gentle.npz',meta=result);print('NEW BEST',json.dumps(result),flush=True)
 Path('/app/experiments/gentle_results.json').write_text(json.dumps(results,indent=2))
 print('DONE',json.dumps(best),flush=True);s.close()
